package com.ruoyi.warehouse.orders;

import com.ruoyi.warehouse.data.WarehouseRepository;
import com.ruoyi.warehouse.returns.ReturnService;
import com.ruoyi.warehouse.support.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.ruoyi.warehouse.orders.OrderServiceTest.map;

class ReturnServiceTest {
    OrderServiceTest f;ReturnService returns;String order;
    @BeforeEach void setup() throws Exception {
        f=new OrderServiceTest();f.database();
        String ddl=Files.readString(Path.of("../sql/warehouse_013_returns.sql")).replaceAll("(?m)^--.*$","").replaceAll(" CHARACTER SET [A-Za-z0-9_]+","").replaceAll(" COLLATE[= ]+[A-Za-z0-9_]+","").replaceAll(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","").replaceAll("\\bJSON\\b","VARCHAR(1000000)");
        for(String sql:ddl.split(";"))if(!sql.isBlank())f.jdbc.execute(sql);
        f.jdbc.execute("CREATE TABLE wh_finance_source(source_key VARCHAR(191) PRIMARY KEY,charge_id VARCHAR(64) UNIQUE REFERENCES wh_record(id),evidence_json VARCHAR(1000000))");
        f.client.put("returnFirst","2.50");f.client.put("returnAdditional","0.75");f.update("client",f.client);
        f.record("quarantine-type","locationTypes",map("name","Quarantine","active",true,"maxUnits",0));
        f.record("quarantine","locations",map("name","Returns custody","warehouse","warehouse","type","Quarantine","custodyOnly",true,"active",true));
        when(f.scope.predicate(eq("returns"),anyList())).thenReturn("1=1");when(f.scope.inventoryPredicate(anyList())).thenReturn("1=1");
        returns=new ReturnService(new WarehouseRepository(f.jdbc,f.scope),f.scope,f.inventory);
        f.receive("product",5,"location","");f.jdbc.update("UPDATE wh_stock_layer SET received_at=?",java.sql.Timestamp.from(java.time.Instant.parse("2024-01-02T03:04:05Z")));
        order=String.valueOf(f.save(null,f.input(5)).get("id"));f.action(order,"allocate");f.action(order,"pick");f.action(order,"despatch");
    }
    @Test void receiveInspectPartialRestockAndClosePreserveAgeAndCannotAllocateCustody(){
        var r=create(3);r=receive(r,3);assertEquals(3,n(r,"held"));assertEquals(3,f.scalar("SELECT SUM(on_hand) FROM wh_inventory"));
        var inventory=WarehouseJson.maps(f.inventory.list(1,20,"","","","").get("rows"));assertTrue(inventory.stream().filter(i->"quarantine".equals(i.get("location"))).allMatch(i->Boolean.TRUE.equals(i.get("quarantined"))&&n(i,"available")==0));
        var other=f.save(null,f.input(1));assertThrows(WarehouseException.class,()->f.action(String.valueOf(other.get("id")),"allocate"));
        String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","PASS","reason","Packaging and goods checked"));
        r=act(r,"restock",map("receipt",receipt,"quantity",1,"location","location","reason","Passed inspection"));assertEquals(2,n(r,"held"));
        assertEquals("2024-01-02T03:04:05Z",WarehouseJson.maps(r.get("dispositions")).get(0).get("result") instanceof Map<?,?> m?m.get("receivedAt"):null);
        var partial=r;assertThrows(WarehouseException.class,()->act(partial,"inspect",map("receipt",receipt,"result","FAIL","reason","Cannot rewrite released evidence")));
        r=act(r,"restock",map("receipt",receipt,"quantity",2,"location","location","reason","Remaining inspected goods"));r=act(r,"close",map("reason","All reconciled"));assertEquals("CLOSED",r.get("status"));assertEquals(3,n(r,"restocked"));assertEquals(0,n(r,"held"));assertEquals(1,f.scalar("SELECT COUNT(*) FROM wh_finance_source"));
    }
    @Test void returnReferenceSearchFindsTheDocumentEvenWhenSkuIsStored(){var r=create(2);var result=returns.list(1,20,String.valueOf(r.get("reference")),"","");assertEquals(1L,result.get("total"));assertEquals(r.get("id"),WarehouseJson.maps(result.get("rows")).get(0).get("id"));}
    @Test void partialReceiptsUseFirstFeeOnceAndSnapshotRates(){var r=create(3);r=receive(r,1);f.client.put("returnFirst",99);f.client.put("returnAdditional",99);f.update("client",f.client);r=receive(r,2);assertEquals(3,n(r,"received"));assertEquals("4.00",chargeTotal());}
    @Test void fractionalRatesUseCumulativeRoundingAcrossPartialReceipts(){f.client.put("returnFirst","0.005");f.client.put("returnAdditional","0.005");f.update("client",f.client);var r=create(3);r=receive(r,1);r=receive(r,1);receive(r,1);assertEquals("0.02",chargeTotal());}
    @Test void productRateOverrideIncludingZeroIsRespected(){f.update("product",map("client","client","sku","SYNTHETIC","active",true,"returnFirst",0,"returnAdditional",1));var r=receive(create(2),2);assertEquals("1.00",chargeTotal());assertEquals(2,n(r,"held"));}
    @Test void scrapsRequireFailedInspectionAndNeverCreateSaleableStock(){var r=receive(create(2),2);String receipt=receipt(r);var before=r;assertThrows(WarehouseException.class,()->act(before,"scrap",map("receipt",receipt,"quantity",2,"reason","Damaged")));r=act(r,"inspect",map("receipt",receipt,"result","FAIL","reason","Damaged casing"));r=act(r,"scrap",map("receipt",receipt,"quantity",2,"reason","Physically destroyed"));assertEquals(2,n(r,"scrapped"));assertEquals(0,f.scalar("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals("3.25",chargeTotal());}
    @Test void openRmasClaimQuantityAndCancellationReleasesOnlyUnreceivedClaims(){var r=create(4);assertThrows(WarehouseException.class,()->create(2));r=act(r,"cancel",map("reason","Customer corrected request"));assertEquals("CANCELLED",r.get("status"));assertNotNull(create(5));}
    @Test void shortReceiptNeedsExplicitAdministratorApprovalAndReleasesUnusedClaim(){var r=receive(create(5),2);String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","FAIL","reason","Broken"));r=act(r,"scrap",map("receipt",receipt,"quantity",2,"reason","Disposed"));var ready=r;assertThrows(WarehouseException.class,()->act(ready,"close",map("reason","Only two arrived")));r=act(r,"close",map("reason","Customer confirmed shortfall","approveShortfall",true));assertEquals("CLOSED",r.get("status"));assertNotNull(create(3));assertThrows(WarehouseException.class,()->create(1));}
    @Test void receivedRmaCannotBeCancelledOrClosedWithHeldGoods(){var r=receive(create(1),1);assertThrows(WarehouseException.class,()->act(r,"cancel",map("reason","No")));assertThrows(WarehouseException.class,()->act(r,"close",map("reason","Still held")));}
    @Test void sourceSelectionsAndRmaLimitsCannotBeExceeded(){var r=create(2);assertThrows(WarehouseException.class,()->receive(r,3));assertThrows(WarehouseException.class,()->act(r,"receive",map("allocation","other","location","quarantine","quantity",1)));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_return_receipt"));}
    @Test void regularLocationCannotReceiveReturnsAndManualMoveCannotEmptyCustody(){var r=create(1);assertThrows(WarehouseException.class,()->act(r,"receive",map("allocation",source(r),"location","location","quantity",1)));receive(r,1);assertThrows(WarehouseException.class,()->f.tx.execute(s->f.inventory.move(map("requestId",UUID.randomUUID().toString(),"action","remove","product","product","warehouse","warehouse","location","quarantine","quantity",1,"reason","Bypass"))));}
    @Test void capacityAndStocktakeFreezeRollbackReleaseAndAllowSameRequestAfterFix(){var r=receive(create(2),2);String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","PASS","reason","Checked"));f.record("count","stocktakes",map("client","client","warehouse","warehouse","status","COUNTING"));f.jdbc.update("INSERT INTO wh_stocktake_lock(client_id,warehouse_id,location_id,stocktake_id) VALUES('client','warehouse','location','count')");var body=body(r,"restock",map("receipt",receipt,"quantity",2,"location","location","reason","Inspected"));String id=String.valueOf(r.get("id"));assertThrows(WarehouseException.class,()->send(id,body));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_return_disposition"));f.jdbc.update("DELETE FROM wh_stocktake_lock");f.update("location",map("name","A-1","warehouse","warehouse","type","Pick","active",true,"maxUnits",1));assertThrows(WarehouseException.class,()->send(id,body));f.update("location",map("name","A-1","warehouse","warehouse","type","Pick","active",true,"maxUnits",2));assertEquals(2,n(send(id,body),"restocked"));}
    @Test void auditFailureRollsBackReceiptFeesLayerAndNonce(){var r=create(2);var b=body(r,"receive",map("allocation",source(r),"location","quarantine","quantity",2));String id=String.valueOf(r.get("id"));f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT reject_return CHECK(action_name<>'RETURN_RECEIVE')");assertThrows(RuntimeException.class,()->send(id,b));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_return_receipt"));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_finance_source"));assertEquals(0,f.scalar("SELECT SUM(on_hand) FROM wh_inventory"));f.jdbc.execute("ALTER TABLE wh_audit DROP CONSTRAINT reject_return");assertEquals(2,n(send(id,b),"received"));}
    @Test void duplicateAndConcurrentReceiptRetryPostsOnlyOnce() throws Exception {var r=create(2);var b=body(r,"receive",map("allocation",source(r),"location","quarantine","quantity",2));String id=String.valueOf(r.get("id"));var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->send(id,b));var c=pool.submit(()->send(id,b));assertEquals(WarehouseJson.write(a.get(10,TimeUnit.SECONDS)),WarehouseJson.write(c.get(10,TimeUnit.SECONDS)));}finally{pool.shutdownNow();}assertEquals(1,f.scalar("SELECT COUNT(*) FROM wh_return_receipt"));assertEquals(1,f.scalar("SELECT COUNT(*) FROM wh_finance_source"));assertEquals(2,f.scalar("SELECT SUM(on_hand) FROM wh_inventory"));}
    @Test void versionNonceMismatchAndRevokedScopeCannotReplay(){var r=create(2);var b=body(r,"receive",map("allocation",source(r),"location","quarantine","quantity",1));String id=String.valueOf(r.get("id"));send(id,b);assertThrows(WarehouseException.class,()->receive(r,1));var changed=new LinkedHashMap<>(b);changed.put("quantity",2);assertThrows(WarehouseException.class,()->send(id,changed));doThrow(WarehouseException.forbidden()).when(f.scope).assertRecord(eq("returns"),anyMap());assertThrows(WarehouseException.class,()->send(id,b));}
    @Test void missingRatesAreNotSilentlyFreeAndUnshippedOrdersAreRejected(){f.client.remove("returnFirst");f.update("client",f.client);assertThrows(WarehouseException.class,()->create(1));f.client.put("returnFirst",0);f.update("client",f.client);order=String.valueOf(f.save(null,f.input(1)).get("id"));assertThrows(WarehouseException.class,()->create(1));}
    @Test void expiredSourceCanBeReceivedAndScrappedButCannotBecomeSaleable(){f.client.put("expiryPolicy","BlockExpired");f.update("client",f.client);f.jdbc.update("UPDATE wh_inventory SET expiry_date='2020-01-01'");var r=receive(create(1),1);String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","PASS","reason","Physical inspection"));var ready=r;assertThrows(WarehouseException.class,()->act(ready,"restock",map("receipt",receipt,"quantity",1,"location","location","reason","Expired")));r=act(r,"inspect",map("receipt",receipt,"result","FAIL","reason","Expired"));assertEquals(1,n(act(r,"scrap",map("receipt",receipt,"quantity",1,"reason","Expired goods destroyed")),"scrapped"));}
    @Test void warningExpiryPolicyRetainsOriginalReleaseBehaviorAndFlagsEvidence(){f.client.put("expiryPolicy","BlockExpired");f.update("client",f.client);f.update("product",map("client","client","sku","SYNTHETIC","active",true,"expiryPolicy","Warn"));f.jdbc.update("UPDATE wh_inventory SET expiry_date='2020-01-01'");var r=receive(create(1),1);String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","PASS","reason","Explicitly reviewed expired return under warning policy"));r=act(r,"restock",map("receipt",receipt,"quantity",1,"location","location","reason","Customer product policy permits release with warning"));assertEquals(1,n(r,"restocked"));assertEquals(true,((Map<?,?>)WarehouseJson.maps(r.get("dispositions")).get(0).get("result")).get("expiredAtDisposition"));}
    @Test void duplicateSerialStockRejectsReceiptWithoutLosingRma(){
        f.tx.execute(s->f.inventory.move(map("requestId",UUID.randomUUID().toString(),"action","add","product","product","warehouse","warehouse","location","location","quantity",1,"reason","Tracked fixture","serial","SERIAL-1")));
        order=String.valueOf(f.save(null,f.input(1)).get("id"));f.action(order,"allocate");f.action(order,"pick");f.action(order,"despatch");
        f.tx.execute(s->f.inventory.move(map("requestId",UUID.randomUUID().toString(),"action","add","product","product","warehouse","warehouse","location","location","quantity",1,"reason","Existing serial received separately","serial","SERIAL-1")));
        var r=create(1);assertThrows(WarehouseException.class,()->receive(r,1));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_return_receipt"));
    }
    @Test void failedDispositionAuditKeepsCustodyAndRetryDoesNotDoubleRestock(){var r=receive(create(1),1);String receipt=receipt(r);r=act(r,"inspect",map("receipt",receipt,"result","PASS","reason","Checked"));var b=body(r,"restock",map("receipt",receipt,"quantity",1,"location","location","reason","Release"));String id=String.valueOf(r.get("id"));f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT reject_release CHECK(action_name<>'RETURN_RESTOCK')");assertThrows(RuntimeException.class,()->send(id,b));assertEquals(1,f.scalar("SELECT SUM(on_hand) FROM wh_inventory WHERE location_id='quarantine'"));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_return_disposition"));f.jdbc.execute("ALTER TABLE wh_audit DROP CONSTRAINT reject_release");send(id,b);send(id,b);assertEquals(1,f.scalar("SELECT SUM(on_hand) FROM wh_inventory WHERE location_id='location'"));assertEquals(1,f.scalar("SELECT COUNT(*) FROM wh_return_disposition"));}
    Map<String,Object> create(long quantity){return f.tx.execute(s->returns.create(map("requestId",UUID.randomUUID().toString(),"order",order,"product","product","quantity",quantity,"reference","RMA-"+UUID.randomUUID(),"reason","Customer return")));}
    Map<String,Object> receive(Map<String,Object> r,long quantity){return act(r,"receive",map("allocation",source(r),"location","quarantine","quantity",quantity));}
    Map<String,Object> act(Map<String,Object> r,String action,Map<String,Object> fields){return send(String.valueOf(r.get("id")),body(r,action,fields));}
    Map<String,Object> body(Map<String,Object> r,String action,Map<String,Object> fields){var b=map("requestId",UUID.randomUUID().toString(),"action",action,"_version",r.get("_version"));b.putAll(fields);return b;}
    Map<String,Object> send(String id,Map<String,Object> body){return f.tx.execute(s->returns.action(id,body));}
    static String source(Map<String,Object> r){return String.valueOf(WarehouseJson.maps(r.get("sources")).get(0).get("id"));}
    static String receipt(Map<String,Object> r){return String.valueOf(WarehouseJson.maps(r.get("receipts")).get(0).get("id"));}
    static long n(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}
    String chargeTotal(){return f.jdbc.queryForList("SELECT business_json FROM wh_record WHERE kind='charges'",String.class).stream().map(WarehouseJson::map).filter(r->"Returns".equals(r.get("type"))).map(r->new java.math.BigDecimal(r.get("amount").toString())).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add).setScale(2).toString();}
}
